command:
// Gallowsmere: a new Hard raid, with Gallowsmere's shopping list on the Raid HUD.
// Run it as the Storyteller once each player owns their Entity: the raid takes every Entity with a player owner.
return game.dontGetForked.raid.start({
  town: "Gallowsmere", difficulty: "hard",
  list: [
    { name: "a new lock for the dungeon", duty: "handyman", essential: true },
    { name: "the silver spoons", duty: "butler", essential: true },
    { name: "black-edged writing paper", duty: "librarian", essential: false },
    { name: "bandages, lots", duty: "tailor", essential: false },
    { name: "a side of bacon", duty: "cook", essential: false }
  ],
});
